CREATE TABLE public.meetings (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text, start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'agendada' CHECK (status IN ('agendada','em_andamento','encerrada','cancelada')), access_type text NOT NULL DEFAULT 'restrito' CHECK (access_type IN ('restrito','aprovacao','aberto')), scope text NOT NULL DEFAULT 'convite' CHECK (scope IN ('convite','curso','link')), course_id uuid REFERENCES public.courses(id), allow_responsible_add_students boolean NOT NULL DEFAULT false, allow_recording boolean NOT NULL DEFAULT true, allow_screen_share boolean NOT NULL DEFAULT true, room_locked boolean NOT NULL DEFAULT false, recording_active boolean NOT NULL DEFAULT false, recording_started_by uuid, recording_started_at timestamptz, meeting_token uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, reminders jsonb NOT NULL DEFAULT '{"h24":true,"h1":true,"start":true}'::jsonb, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (end_at > start_at), CHECK (scope <> 'curso' OR course_id IS NOT NULL)
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.meetings TO authenticated;
GRANT ALL ON public.meetings TO service_role;
ALTER TABLE public.meetings ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.meeting_responsibles (meeting_id uuid NOT NULL REFERENCES public.meetings(id) ON DELETE CASCADE, user_id uuid NOT NULL, added_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(meeting_id,user_id));
GRANT SELECT, INSERT, DELETE ON public.meeting_responsibles TO authenticated;
GRANT ALL ON public.meeting_responsibles TO service_role;
ALTER TABLE public.meeting_responsibles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.meeting_participants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES public.meetings(id) ON DELETE CASCADE, user_id uuid NOT NULL, invited_by uuid NOT NULL, status text NOT NULL DEFAULT 'convidado' CHECK (status IN ('convidado','aprovado','removido')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(meeting_id,user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.meeting_participants TO authenticated;
GRANT ALL ON public.meeting_participants TO service_role;
ALTER TABLE public.meeting_participants ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.meeting_access_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES public.meetings(id) ON DELETE CASCADE, user_id uuid NOT NULL, status text NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','aprovado','recusado')), requested_at timestamptz NOT NULL DEFAULT now(), approved_by uuid, approved_at timestamptz, UNIQUE(meeting_id,user_id));
GRANT SELECT, INSERT, UPDATE ON public.meeting_access_requests TO authenticated;
GRANT ALL ON public.meeting_access_requests TO service_role;
ALTER TABLE public.meeting_access_requests ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.meeting_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES public.meetings(id) ON DELETE CASCADE, user_id uuid NOT NULL, joined_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), left_at timestamptz, duration_seconds integer NOT NULL DEFAULT 0, UNIQUE(id,meeting_id));
GRANT SELECT ON public.meeting_sessions TO authenticated;
GRANT ALL ON public.meeting_sessions TO service_role;
ALTER TABLE public.meeting_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.meeting_chat (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES public.meetings(id) ON DELETE CASCADE, user_id uuid NOT NULL, message text NOT NULL CHECK(length(message) BETWEEN 1 AND 1000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.meeting_chat TO authenticated;
GRANT ALL ON public.meeting_chat TO service_role;
ALTER TABLE public.meeting_chat ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.meeting_signals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES public.meetings(id) ON DELETE CASCADE, sender_id uuid NOT NULL, recipient_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('offer','answer','ice','control','state')), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.meeting_signals TO authenticated;
GRANT ALL ON public.meeting_signals TO service_role;
ALTER TABLE public.meeting_signals ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.meeting_recordings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES public.meetings(id) ON DELETE CASCADE, file_name text NOT NULL, file_url text, storage_type text NOT NULL DEFAULT 'local', duration_seconds integer NOT NULL DEFAULT 0, file_size bigint NOT NULL DEFAULT 0, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.meeting_recordings TO authenticated;
GRANT ALL ON public.meeting_recordings TO service_role;
ALTER TABLE public.meeting_recordings ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.meeting_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES public.meetings(id) ON DELETE CASCADE, actor_id uuid, action text NOT NULL, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.meeting_audit TO authenticated;
GRANT ALL ON public.meeting_audit TO service_role;
ALTER TABLE public.meeting_audit ENABLE ROW LEVEL SECURITY;
CREATE INDEX meeting_participants_user_idx ON public.meeting_participants(user_id,meeting_id);
CREATE INDEX meeting_sessions_meeting_idx ON public.meeting_sessions(meeting_id,user_id);
CREATE INDEX meeting_signals_recipient_idx ON public.meeting_signals(recipient_id,meeting_id,created_at);
CREATE INDEX meeting_chat_idx ON public.meeting_chat(meeting_id,created_at);
CREATE OR REPLACE FUNCTION public.meeting_is_manager(_id uuid, _uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT _uid IS NOT NULL AND (public.has_role(_uid,'admin') OR EXISTS(SELECT 1 FROM public.meeting_responsibles r WHERE r.meeting_id=_id AND r.user_id=_uid)) $$;
REVOKE ALL ON FUNCTION public.meeting_is_manager(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.meeting_is_manager(uuid,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.meeting_can_enter(_id uuid, _uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT _uid IS NOT NULL AND EXISTS(SELECT 1 FROM public.meetings m WHERE m.id=_id AND m.status NOT IN ('cancelada','encerrada') AND (public.meeting_is_manager(_id,_uid) OR (NOT m.room_locked AND (m.access_type='aberto' OR EXISTS(SELECT 1 FROM public.meeting_participants p WHERE p.meeting_id=_id AND p.user_id=_uid AND p.status IN ('convidado','aprovado')) OR EXISTS(SELECT 1 FROM public.meeting_access_requests ar WHERE ar.meeting_id=_id AND ar.user_id=_uid AND ar.status='aprovado') OR (m.scope='curso' AND EXISTS(SELECT 1 FROM public.enrollments e WHERE e.course_id=m.course_id AND e.user_id=_uid)))))) $$;
REVOKE ALL ON FUNCTION public.meeting_can_enter(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.meeting_can_enter(uuid,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.meeting_can_view(_id uuid, _uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.meeting_is_manager(_id,_uid) OR EXISTS(SELECT 1 FROM public.meeting_participants p WHERE p.meeting_id=_id AND p.user_id=_uid AND p.status IN ('convidado','aprovado')) OR EXISTS(SELECT 1 FROM public.meeting_access_requests a WHERE a.meeting_id=_id AND a.user_id=_uid AND a.status='aprovado') OR EXISTS(SELECT 1 FROM public.meetings m JOIN public.enrollments e ON e.course_id=m.course_id AND e.user_id=_uid WHERE m.id=_id AND m.scope='curso') $$;
REVOKE ALL ON FUNCTION public.meeting_can_view(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.meeting_can_view(uuid,uuid) TO authenticated,service_role;
CREATE POLICY meetings_view ON public.meetings FOR SELECT TO authenticated USING(public.meeting_can_view(id,auth.uid()));
CREATE POLICY meetings_admin_insert ON public.meetings FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') AND created_by=auth.uid() AND access_type IN ('restrito','aprovacao','aberto'));
CREATE POLICY meetings_admin_update ON public.meetings FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY meetings_admin_delete ON public.meetings FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY responsibles_view ON public.meeting_responsibles FOR SELECT TO authenticated USING(public.meeting_can_view(meeting_id,auth.uid()));
CREATE POLICY responsibles_insert ON public.meeting_responsibles FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY responsibles_delete ON public.meeting_responsibles FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY participants_view ON public.meeting_participants FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.meeting_is_manager(meeting_id,auth.uid()));
CREATE POLICY participants_insert ON public.meeting_participants FOR INSERT TO authenticated WITH CHECK(invited_by=auth.uid() AND (public.has_role(auth.uid(),'admin') OR (public.meeting_is_manager(meeting_id,auth.uid()) AND (SELECT allow_responsible_add_students FROM public.meetings WHERE id=meeting_id))) AND EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=meeting_participants.user_id AND ur.role IN ('aluno','cooperado')));
CREATE POLICY participants_update ON public.meeting_participants FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR (public.meeting_is_manager(meeting_id,auth.uid()) AND (SELECT allow_responsible_add_students FROM public.meetings WHERE id=meeting_id))) WITH CHECK(public.has_role(auth.uid(),'admin') OR (public.meeting_is_manager(meeting_id,auth.uid()) AND (SELECT allow_responsible_add_students FROM public.meetings WHERE id=meeting_id)));
CREATE POLICY participants_delete ON public.meeting_participants FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin') OR (public.meeting_is_manager(meeting_id,auth.uid()) AND (SELECT allow_responsible_add_students FROM public.meetings WHERE id=meeting_id)));
CREATE POLICY requests_view ON public.meeting_access_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.meeting_is_manager(meeting_id,auth.uid()));
CREATE POLICY sessions_view ON public.meeting_sessions FOR SELECT TO authenticated USING(public.meeting_can_view(meeting_id,auth.uid()));
CREATE POLICY chat_view ON public.meeting_chat FOR SELECT TO authenticated USING(public.meeting_can_view(meeting_id,auth.uid()));
CREATE POLICY chat_send ON public.meeting_chat FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.meeting_can_enter(meeting_id,auth.uid()) AND EXISTS(SELECT 1 FROM public.meetings m WHERE m.id=meeting_id AND m.status='em_andamento'));
CREATE POLICY signals_read ON public.meeting_signals FOR SELECT TO authenticated USING(recipient_id=auth.uid() AND public.meeting_can_enter(meeting_id,auth.uid()));
CREATE POLICY signals_send ON public.meeting_signals FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND sender_id<>recipient_id AND public.meeting_can_enter(meeting_id,auth.uid()) AND public.meeting_can_enter(meeting_id,recipient_id) AND EXISTS(SELECT 1 FROM public.meetings m WHERE m.id=meeting_id AND m.status='em_andamento') AND (kind NOT IN ('control','state') OR public.meeting_is_manager(meeting_id,auth.uid())));
CREATE POLICY recordings_view ON public.meeting_recordings FOR SELECT TO authenticated USING(public.meeting_is_manager(meeting_id,auth.uid()));
CREATE POLICY recordings_insert ON public.meeting_recordings FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND public.meeting_is_manager(meeting_id,auth.uid()) AND storage_type='local' AND file_url IS NULL AND EXISTS(SELECT 1 FROM public.meetings m WHERE m.id=meeting_id AND m.allow_recording));
CREATE POLICY recordings_delete ON public.meeting_recordings FOR DELETE TO authenticated USING(public.meeting_is_manager(meeting_id,auth.uid()));
CREATE POLICY audit_view ON public.meeting_audit FOR SELECT TO authenticated USING(public.meeting_is_manager(meeting_id,auth.uid()));
CREATE OR REPLACE FUNCTION public.meeting_notify_invite() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status IN ('convidado','aprovado') AND (TG_OP='INSERT' OR OLD.status='removido') THEN INSERT INTO public.notifications(user_id,type,title,message,link) SELECT NEW.user_id,'reuniao','Convite para reunião',format('Você foi convidado para "%s" em %s.',m.title,to_char(m.start_at AT TIME ZONE 'America/Fortaleza','DD/MM às HH24:MI')),'/reuniao/'||m.meeting_token::text FROM public.meetings m WHERE m.id=NEW.meeting_id; END IF; RETURN NEW; END $$;
CREATE TRIGGER meeting_invite_notification AFTER INSERT OR UPDATE ON public.meeting_participants FOR EACH ROW EXECUTE FUNCTION public.meeting_notify_invite();
CREATE OR REPLACE FUNCTION public.meeting_audit_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.meeting_audit(meeting_id,actor_id,action,details) VALUES(COALESCE(NEW.id,OLD.id),auth.uid(),CASE WHEN TG_OP='INSERT' THEN 'criada' ELSE 'alterada' END, CASE WHEN TG_OP='UPDATE' THEN jsonb_build_object('status',NEW.status,'acesso',NEW.access_type,'link_regenerado',OLD.meeting_token<>NEW.meeting_token) ELSE '{}'::jsonb END); RETURN NEW; END $$;
CREATE TRIGGER meeting_audit_trigger AFTER INSERT OR UPDATE ON public.meetings FOR EACH ROW EXECUTE FUNCTION public.meeting_audit_change();
CREATE OR REPLACE FUNCTION public.meeting_link_info(_token uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.meetings%ROWTYPE; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Autenticação obrigatória'; END IF; SELECT * INTO m FROM public.meetings WHERE meeting_token=_token; IF NOT FOUND THEN RETURN jsonb_build_object('found',false); END IF; RETURN jsonb_build_object('found',true,'id',m.id,'title',m.title,'start_at',m.start_at,'status',m.status,'access_type',m.access_type,'allowed',public.meeting_can_enter(m.id,auth.uid()),'manager',public.meeting_is_manager(m.id,auth.uid()),'requested',EXISTS(SELECT 1 FROM public.meeting_access_requests a WHERE a.meeting_id=m.id AND a.user_id=auth.uid() AND a.status='pendente')); END $$;
REVOKE ALL ON FUNCTION public.meeting_link_info(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.meeting_link_info(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.meeting_request_entry(_token uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.meetings%ROWTYPE; BEGIN SELECT * INTO m FROM public.meetings WHERE meeting_token=_token; IF auth.uid() IS NULL OR NOT FOUND OR m.access_type<>'aprovacao' OR m.status IN ('cancelada','encerrada') THEN RAISE EXCEPTION 'Solicitação indisponível'; END IF; INSERT INTO public.meeting_access_requests(meeting_id,user_id,status) VALUES(m.id,auth.uid(),'pendente') ON CONFLICT(meeting_id,user_id) DO UPDATE SET status='pendente',requested_at=now(),approved_by=NULL,approved_at=NULL; END $$;
REVOKE ALL ON FUNCTION public.meeting_request_entry(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.meeting_request_entry(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.meeting_decide_entry(_request_id uuid,_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.meeting_access_requests%ROWTYPE; BEGIN SELECT * INTO r FROM public.meeting_access_requests WHERE id=_request_id FOR UPDATE; IF NOT FOUND OR NOT public.meeting_is_manager(r.meeting_id,auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; UPDATE public.meeting_access_requests SET status=CASE WHEN _approve THEN 'aprovado' ELSE 'recusado' END,approved_by=auth.uid(),approved_at=now() WHERE id=_request_id; INSERT INTO public.meeting_audit(meeting_id,actor_id,action,details) VALUES(r.meeting_id,auth.uid(),'solicitacao_decidida',jsonb_build_object('user_id',r.user_id,'aprovado',_approve)); END $$;
REVOKE ALL ON FUNCTION public.meeting_decide_entry(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.meeting_decide_entry(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.meeting_set_state(_id uuid,_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.meetings%ROWTYPE; BEGIN SELECT * INTO m FROM public.meetings WHERE id=_id FOR UPDATE; IF NOT FOUND OR NOT public.meeting_is_manager(_id,auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF _action='iniciar' AND m.status='agendada' THEN UPDATE public.meetings SET status='em_andamento',updated_at=now() WHERE id=_id; ELSIF _action='encerrar' AND m.status='em_andamento' THEN UPDATE public.meetings SET status='encerrada',recording_active=false,updated_at=now() WHERE id=_id; UPDATE public.meeting_sessions SET left_at=now(),duration_seconds=GREATEST(0,extract(epoch FROM (LEAST(now(),last_seen_at+interval '45 seconds')-joined_at))::int) WHERE meeting_id=_id AND left_at IS NULL; ELSIF _action='cancelar' AND m.status='agendada' THEN UPDATE public.meetings SET status='cancelada',updated_at=now() WHERE id=_id; ELSIF _action='bloquear' AND m.status='em_andamento' THEN UPDATE public.meetings SET room_locked=true WHERE id=_id; ELSIF _action='desbloquear' AND m.status='em_andamento' THEN UPDATE public.meetings SET room_locked=false WHERE id=_id; ELSIF _action='gravar' AND m.status='em_andamento' AND m.allow_recording THEN UPDATE public.meetings SET recording_active=true,recording_started_by=auth.uid(),recording_started_at=now() WHERE id=_id; ELSIF _action='parar_gravacao' AND m.recording_active THEN UPDATE public.meetings SET recording_active=false WHERE id=_id; ELSE RAISE EXCEPTION 'Ação indisponível'; END IF; INSERT INTO public.meeting_audit(meeting_id,actor_id,action) VALUES(_id,auth.uid(),_action); END $$;
REVOKE ALL ON FUNCTION public.meeting_set_state(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.meeting_set_state(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.meeting_join(_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF NOT public.meeting_can_enter(_id,auth.uid()) OR NOT EXISTS(SELECT 1 FROM public.meetings WHERE id=_id AND status='em_andamento') THEN RAISE EXCEPTION 'Você não possui autorização para participar desta reunião.'; END IF; SELECT id INTO sid FROM public.meeting_sessions WHERE meeting_id=_id AND user_id=auth.uid() AND left_at IS NULL AND last_seen_at>now()-interval '90 seconds' ORDER BY joined_at DESC LIMIT 1; IF sid IS NULL THEN INSERT INTO public.meeting_sessions(meeting_id,user_id) VALUES(_id,auth.uid()) RETURNING id INTO sid; END IF; RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.meeting_join(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.meeting_join(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.meeting_heartbeat(_sid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.meeting_sessions SET last_seen_at=now(),duration_seconds=GREATEST(duration_seconds,extract(epoch FROM (now()-joined_at))::int) WHERE id=_sid AND user_id=auth.uid() AND left_at IS NULL AND public.meeting_can_enter(meeting_id,auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.meeting_heartbeat(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.meeting_heartbeat(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.meeting_leave(_sid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.meeting_sessions SET left_at=now(),duration_seconds=GREATEST(0,extract(epoch FROM (LEAST(now(),last_seen_at+interval '45 seconds')-joined_at))::int) WHERE id=_sid AND user_id=auth.uid() AND left_at IS NULL; END $$;
REVOKE ALL ON FUNCTION public.meeting_leave(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.meeting_leave(uuid) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.meetings;
ALTER PUBLICATION supabase_realtime ADD TABLE public.meeting_sessions;
ALTER PUBLICATION supabase_realtime ADD TABLE public.meeting_chat;
ALTER PUBLICATION supabase_realtime ADD TABLE public.meeting_signals;
ALTER PUBLICATION supabase_realtime ADD TABLE public.meeting_access_requests;